"},{"path":"src/data.js","language":"javascript","content":"export const mealCatalog = [
  { id: 'rice-beans', name: 'Rice and beans', ingredients: ['rice', 'beans'] },
  { id: 'tomato-pasta', name: 'Tomato pasta', ingredients: ['pasta', 'tomato'] },
  { id: 'lentil-stew', name: 'Lentil stew', ingredients: ['lentils', 'tomato'] },
  { id: 'vegetable-rice', name: 'Vegetable rice', ingredients: ['rice', 'mixedVegetables'] },
  { id: 'chickpea-couscous', name: 'Chickpea couscous', ingredients: ['chickpeas', 'couscous'] },
  { id: 'potatoes-peas', name: 'Potatoes and peas', ingredients: ['potatoes', 'peas'] },
  { id: 'vegetable-oats', name: 'Vegetable oats', ingredients: ['oats', 'mixedVegetables'] }
];

export const demoPricesCents = {
  oats: 30,
  peas: 35,
  rice: 25,
  beans: 50,
  pasta: 40,
  tomato: 30,
  lentils: 45,
  couscous: 40,
  potatoes: 35,
  chickpeas: 50,
  mixedVegetables: 60
};
"},{"path":"src/planner.js","language":"javascript","content":"import { demoPricesCents, mealCatalog } from './data.js';

export function validateInputs(budgetCents, familySize) {
  if (budgetCents === '' || budgetCents === null || budgetCents === undefined) {
    return 'budgetCents is required.';
  }

  if (familySize === '' || familySize === null || familySize === undefined) {
    return 'familySize is required.';
  }

  const budgetNumber = Number(budgetCents);
  const familyNumber = Number(familySize);

  if (!Number.isInteger(budgetNumber)) {
    return 'budgetCents must be an integer.';
  }

  if (!Number.isInteger(familyNumber)) {
    return 'familySize must be an integer.';
  }

  if (budgetNumber < 0) {
    return 'budgetCents must be greater than or equal to 0.';
  }

  if (familyNumber < 1 || familyNumber > 12) {
    return 'familySize must be between 1 and 12.';
  }

  return '';
}

export function buildPlan(budgetCents, familySize) {
  const validationError = validateInputs(budgetCents, familySize);

  if (validationError) {
    return {
      error: validationError,
      status: '',
      days: [],
      shoppingList: [],
      totalCostCents: 0,
      requiredBudgetCents: 0
    };
  }

  const normalizedBudget = Number(budgetCents);
  const normalizedFamilySize = Number(familySize);
  const shoppingMap = {};

  const days = mealCatalog.map((meal, index) => {
    const ingredientLines = meal.ingredients.map((ingredient) => {
      const quantity = normalizedFamilySize;
      const unitPriceCents = demoPricesCents[ingredient];
      const lineCostCents = quantity * unitPriceCents;

      shoppingMap[ingredient] = (shoppingMap[ingredient] || 0) + quantity;

      return {
        ingredient,
        quantity,
        unitPriceCents,
        lineCostCents
      };
    });

    const mealCostCents = ingredientLines.reduce((sum, line) => sum + line.lineCostCents, 0);

    return {
      dayNumber: index + 1,
      mealId: meal.id,
      mealName: meal.name,
      ingredients: ingredientLines,
      mealCostCents
    };
  });

  const shoppingList = Object.keys(shoppingMap)
    .sort()
    .map((ingredient) => ({
      ingredient,
      quantity: shoppingMap[ingredient],
      unitPriceCents: demoPricesCents[ingredient],
      lineCostCents: shoppingMap[ingredient] * demoPricesCents[ingredient]
    }));

  const totalCostCents = days.reduce((sum, day) => sum + day.mealCostCents, 0);
  const requiredBudgetCents = totalCostCents;

  if (totalCostCents <= normalizedBudget) {
    return {
      error: '',
      status: 'feasible',
      days,
      shoppingList,
      totalCostCents,
      requiredBudgetCents
    };
  }

  return {
    error: '',
    status: 'insufficient_budget',
    days: [],
    shoppingList: [],
    totalCostCents,
    requiredBudgetCents
  };
}
"},{"path":"src/App.jsx","language":"javascript","content":"import React, { useMemo, useState } from 'react';
import { buildPlan } from './planner.js';

function formatCents(value) {
  return String(value);
}

export default function App() {
  const [budgetCents, setBudgetCents] = useState('12000');
  const [familySize, setFamilySize] = useState('4');

  const result = useMemo(() => buildPlan(budgetCents, familySize), [budgetCents, familySize]);

  return (
    <main style={{ fontFamily: 'Arial, sans-serif', margin: '0 auto', maxWidth: 960, padding: 24, lineHeight: 1.5 }}>
      <h1>Seven distinct dinners within a budget</h1>
      <p>Demonstration prices only — not live grocery prices or nutritional advice</p>

      <section style={{ border: '1px solid #ccc', padding: 16, borderRadius: 8, marginBottom: 16 }}>
        <h2>Inputs</h2>
        <div style={{ display: 'grid', gap: 12, maxWidth: 320 }}>
          <label>
            Budget (cents)
            <input
              type="number"
              step="1"
              value={budgetCents}
              onChange={(event) => setBudgetCents(event.target.value)}
              style={{ display: 'block', width: '100%', padding: 8, marginTop: 4 }}
            />
          </label>
          <label>
            Family size
            <input
              type="number"
              step="1"
              value={familySize}
              onChange={(event) => setFamilySize(event.target.value)}
              style={{ display: 'block', width: '100%', padding: 8, marginTop: 4 }}
            />
          </label>
        </div>
      </section>

      {result.error ? (
        <section style={{ background: '#ffe9e9', border: '1px solid #d33', padding: 16, borderRadius: 8, marginBottom: 16 }}>
          <h2>Validation error</h2>
          <p>{result.error}</p>
        </section>
      ) : null}

      {!result.error ? (
        <>
          <section style={{ border: '1px solid #ccc', padding: 16, borderRadius: 8, marginBottom: 16 }}>
            <h2>Result</h2>
            <p><strong>Status:</strong> {result.status}</p>
            <p><strong>Total cost cents:</strong> {formatCents(result.totalCostCents)}</p>
            <p><strong>Required budget cents:</strong> {formatCents(result.requiredBudgetCents)}</p>
            {result.status === 'insufficient_budget' ? (
              <p>The seven-day plan costs more than the provided budget, so no feasible plan is returned.</p>
            ) : null}
          </section>

          <section style={{ border: '1px solid #ccc', padding: 16, borderRadius: 8, marginBottom: 16 }}>
            <h2>Days</h2>
            {result.days.length === 0 ? (
              <p>No days returned.</p>
            ) : (
              <div style={{ display: 'grid', gap: 12 }}>
                {result.days.map((day) => (
                  <article key={day.dayNumber} style={{ border: '1px solid #ddd', borderRadius: 8, padding: 12 }}>
                    <h3>Day {day.dayNumber}: {day.mealName}</h3>
                    <p>Meal cost cents: {formatCents(day.mealCostCents)}</p>
                    <ul>
                      {day.ingredients.map((line) => (
                        <li key={line.ingredient}>
                          {line.ingredient}: quantity {line.quantity}, unit price {formatCents(line.unitPriceCents)}, line cost {formatCents(line.lineCostCents)}
                        </li>
                      ))}
                    </ul>
                  </article>
                ))}
              </div>
            )}
          </section>

          <section style={{ border: '1px solid #ccc', padding: 16, borderRadius: 8 }}>
            <h2>Shopping list</h2>
            {result.shoppingList.length === 0 ? (
              <p>No shopping list returned.</p>
            ) : (
              <table style={{ borderCollapse: 'collapse', width: '100%' }}>
                <thead>
                  <tr>
                    <th style={{ borderBottom: '1px solid #ccc', textAlign: 'left', padding: 8 }}>Ingredient</th>
                    <th style={{ borderBottom: '1px solid #ccc', textAlign: 'left', padding: 8 }}>Quantity</th>
                    <th style={{ borderBottom: '1px solid #ccc', textAlign: 'left', padding: 8 }}>Unit price cents</th>
                    <th style={{ borderBottom: '1px solid #ccc', textAlign: 'left', padding: 8 }}>Line cost cents</th>
                  </tr>
                </thead>
                <tbody>
                  {result.shoppingList.map((item) => (
                    <tr key={item.ingredient}>
                      <td style={{ borderBottom: '1px solid #eee', padding: 8 }}>{item.ingredient}</td>
                      <td style={{ borderBottom: '1px solid #eee', padding: 8 }}>{item.quantity}</td>
                      <td style={{ borderBottom: '1px solid #eee', padding: 8 }}>{formatCents(item.unitPriceCents)}</td>
                      <td style={{ borderBottom: '1px solid #eee', padding: 8 }}>{formatCents(item.lineCostCents)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </section>
        </>
      ) : null}
    </main>
  );
}
"}],"manifest":{"framework":"React 19 + Vite","language":"javascript","entrypoint":"src/main.jsx","installCommand":"npm install","runCommand":"npm run dev","buildCommand":"npm run build","deployTarget":"cloudflare-pages"},"notes":"Scaffolded a client-only React/Vite app with deterministic planner logic, local certified data, visible validation errors, and README manual checks. Implemented the two specified outcomes and exact disclaimer. Left no backend/services/credentials. Scope traces mainly to Objective, I/O contract, Pricing and provenance, Calculation, Success criteria, and Delivery scope."}
